style.css:
@-moz-document domain("roblox.com") {
/* 기본 바탕을 전부 투명으로 (html/body) */
  html, body {
    margin: 0;
    padding: 0;
    background: transparent !important;
  }

  /* 진짜 배경은 html에 직접 넣기 */
  html {
    background-image: url("https://i.pinimg.com/736x/a5/b3/36/a5b336ec9736d8c16f092af14ec2f61a.jpg") !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  /* 대부분의 큰 컨테이너 배경 투명 처리 */
  body,
  #app,
  #rbx-body,
  .rbx-body,
  .site-wrap,
  .page-content,
  .content,
  .container-main,
  .main-content,
  .react-app,
  [class*="page"],
  [class*="Page"],
  [class*="content"],
  [class*="Content"],
  [class*="theme"],
  [class*="Theme"] {
    background: transparent !important;
  }

  /* 진짜 강제: 많은 요소의 background-color 날리기 (필요하면 켜기) */
  /*
  * {
    background-color: transparent !important;
  }
  */

  /* 상단 네비게이션은 반투명 검정 */
  header,
  nav,
  .navbar,
  .rbx-navbar,
  [class*="navbar"],
  [class*="NavBar"],
  [class*="nav-bar"] {
    background: rgba(0, 0, 0, 0.45) !important;
    backdrop-filter: blur(4px) !important;
  }
}
